const item = $input.first();
const j = item.json;
const bin = item.binary || {};
const key = Object.keys(bin)[0];
if (!key) { throw new Error('No pitch book file was received. Upload a PDF or TXT.'); }
const f = bin[key];
const fname = String(f.fileName || '').toLowerCase();
const isPdf = String(f.mimeType || '').includes('pdf') || fname.endsWith('.pdf');
// Founder identity is kept ONLY here, to be used later for scrubbing. It never reaches the outputs.
return [{
  json: {
    founderName: j['Founder Name'] || '',
    university: j['University'] || '',
    startupCode: j['Startup Code'] || '',
    isPdf: isPdf
  },
  binary: { data: f }
}];

const meta = $('Normalize Upload').first().json;
const j = $input.first().json;
let raw = j.text ?? (j.data && j.data.text) ?? j.data ?? '';
if (typeof raw !== 'string') { raw = JSON.stringify(raw); }
raw = raw.replace(/\r/g, '');

// Only these labelled details are read. Everything else in the pitch book is ignored.
const mult = { k: 1e3, thousand: 1e3, m: 1e6, million: 1e6 };
const num = (labels) => {
  const L = labels.map(l => l.replace(/ /g, '\\s+')).join('|');
  const re = new RegExp('(?:' + L + ')\\s*[:\\-=]?\\s*(?:USD|US\\$|\\$)?\\s*([0-9][0-9,]*(?:\\.[0-9]+)?)\\s*(k|m|million|thousand)?\\b', 'i');
  const m = raw.match(re);
  if (!m) return null;
  let v = Number(m[1].replace(/,/g, ''));
  if (m[2]) v = v * mult[m[2].toLowerCase()];
  return v;
};

const rev   = num(['Monthly Revenue', 'Monthly Recurring Revenue', 'MRR']);
const cost  = num(['Monthly Costs', 'Monthly Expenses']);
const u0    = num(['Users Last Month', 'Previous Month Users']);
const u1    = num(['Users This Month', 'Current Users']);
const cash  = num(['Cash in Bank', 'Cash Balance', 'Cash on Hand']);
const ask   = num(['Funding Ask', 'Funding Request', 'Amount Raising']);

let industry = 'Other';
const im = raw.match(/Industry\s*[:\-]\s*([A-Za-z][A-Za-z &\/]{1,30})/i);
if (im) {
  const s = im[1].toLowerCase();
  const known = ['SaaS', 'Fintech', 'Health', 'Consumer', 'Hardware'];
  industry = known.find(k => s.includes(k.toLowerCase())) || 'Other';
}

let desc = '';
const hm = raw.match(/(business summary|about the business|what we do)\s*:?\s*/i);
if (hm) {
  let t = raw.slice(hm.index + hm[0].length);
  const stop = t.search(/\n\s*(team|founders?|key metrics|traction|financials|funding|contact|the ask)\b/i);
  if (stop > 0) t = t.slice(0, stop);
  desc = t.replace(/\s+/g, ' ').trim().slice(0, 900);
}

const fields = { 'Monthly Revenue': rev, 'Monthly Costs': cost, 'Users Last Month': u0, 'Users This Month': u1, 'Cash in Bank': cash, 'Funding Ask': ask };
const missing = Object.keys(fields).filter(k => fields[k] === null);
const code = String(meta.startupCode || '').trim() || ('BLIND-' + Date.now().toString(36).toUpperCase());

return [{ json: {
  received_at: new Date().toISOString(),
  startup_code: code,
  industry: industry,
  rev: rev, cost: cost, u0: u0, u1: u1, cash: cash, ask: ask,
  description_raw: desc,
  missing: missing,
  missing_count: missing.length,
  all_found: missing.length === 0
} }];

const d = $input.first().json;
const meta = $('Normalize Upload').first().json;
const escRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
let text = String(d.description_raw || '');
let removed = 0;
const rep = (re, tag) => { text = text.replace(re, () => { removed++; return tag; }); };

// names of the founder
String(meta.founderName || '').split(/\s+/).map(t => t.replace(/[^a-zA-Z]/g, '')).filter(t => t.length > 2)
  .forEach(t => rep(new RegExp('\\b' + escRe(t) + '\\b', 'gi'), '[NAME REMOVED]'));
// university
const uni = String(meta.university || '').replace(/[^a-zA-Z ]/g, '').trim();
if (uni.length > 2) { rep(new RegExp(escRe(uni), 'gi'), '[SCHOOL REMOVED]'); }
// links, emails, handles
rep(/https?:\/\/[^\s]+/gi, '[LINK REMOVED]');
rep(/www\.[^\s]+/gi, '[LINK REMOVED]');
rep(/[^\s]+@[^\s]+/g, '[EMAIL REMOVED]');
rep(/@[A-Za-z0-9_]{2,}/g, '[HANDLE REMOVED]');
// pedigree and prestige
rep(/(harvard|stanford|oxford|cambridge|princeton|yale|columbia|berkeley|wharton|insead|caltech|y combinator|ycombinator|ex-google|ex-meta|ex-apple|ex-amazon|ex-microsoft|ex-mckinsey|forbes 30|techcrunch|ivy league)/gi, '[PEDIGREE REMOVED]');
rep(/\b(MIT|IIT|IIM)\b/g, '[PEDIGREE REMOVED]');
// hype
rep(/(world-class|visionary|revolutionary|disruptive|passionate|unicorn|rockstar|game-changing|game changer|cutting-edge|best-in-class)/gi, '[HYPE REMOVED]');

return [{ json: { ...d, description_raw: undefined, blind_description: text || '(no description provided)', redactions_made: removed } }];

const d = $input.first().json;
const clamp = (v, a, b) => Math.min(Math.max(v, a), b);
const r1 = v => Math.round(v * 10) / 10;

const rev = d.rev, cost = d.cost, u0 = d.u0, u1 = d.u1, cash = d.cash, ask = d.ask;
const burn = Math.max(cost - rev, 0);
const margin = rev > 0 ? ((rev - cost) / rev) * 100 : -100;
const growth = u0 > 0 ? ((u1 - u0) / u0) * 100 : 0;
const runway = burn === 0 ? 99 : cash / burn;
const askMult = rev > 0 ? ask / (rev * 12) : 99;

const sGrowth = clamp(growth / 20, 0, 1) * 30;
const sMargin = clamp((margin + 100) / 100, 0, 1) * 25;
const sRunway = clamp(runway / 18, 0, 1) * 25;
const sAsk = clamp((15 - askMult) / 12, 0, 1) * 20;
const total = Math.round(sGrowth + sMargin + sRunway + sAsk);
const verdict = total >= 70 ? 'ADVANCE' : total >= 45 ? 'REVIEW' : 'DECLINE';

return [{ json: {
  received_at: d.received_at,
  startup_code: d.startup_code,
  industry: d.industry,
  monthly_revenue: rev,
  monthly_costs: cost,
  net_monthly_burn: burn,
  profit_margin_pct: r1(margin),
  users_last_month: u0,
  users_this_month: u1,
  user_growth_mom_pct: r1(growth),
  cash_in_bank: cash,
  runway_months: runway >= 99 ? 'Profitable' : r1(runway),
  funding_ask: ask,
  ask_to_annual_revenue_x: askMult >= 99 ? 'n/a' : r1(askMult),
  score_growth_30: r1(sGrowth),
  score_margin_25: r1(sMargin),
  score_runway_25: r1(sRunway),
  score_ask_20: r1(sAsk),
  total_score_100: total,
  verdict: verdict,
  missing_fields: '',
  redactions_made: d.redactions_made,
  blind_description: d.blind_description
} }];
